@import "@fontsource-variable/manrope";

/* Light (faithful): white page, #101010 ink, brand blue #218aff, pale grey #eee cards,
   a lighter blue (#469bfa) as the glow behind gradients. */
:root {
  --background: rgb(255 255 255);
  --foreground: rgb(16 16 16);
  --card: rgb(255 255 255);
  --card-foreground: rgb(16 16 16);
  --popover: rgb(255 255 255);
  --popover-foreground: rgb(16 16 16);
  --primary: rgb(33 138 255);
  --primary-foreground: rgb(255 255 255);
  --secondary: rgb(64 64 64);
  --secondary-foreground: rgb(242 242 242);
  --muted: rgb(238 238 238);
  --muted-foreground: rgb(16 16 16 / 60%);
  --accent: rgb(16 16 16 / 5%);
  --accent-foreground: rgb(16 16 16);
  --destructive: rgb(220 50 50);
  --destructive-foreground: rgb(255 255 255);
  --border: rgb(16 16 16 / 8%);
  --input: rgb(16 16 16 / 15%);
  --ring: rgb(33 138 255);
  --highlight: rgb(251 158 121);
  --highlight-foreground: rgb(16 16 16);
  --glow: rgb(70 155 250);
  --chart-1: rgb(33 138 255);
  --chart-2: rgb(251 158 121);
  --chart-3: rgb(120 110 160);
  --chart-4: rgb(90 130 90);
  --chart-5: rgb(170 110 80);
  --sidebar: rgb(238 238 238);
  --sidebar-foreground: rgb(16 16 16);
  --sidebar-primary: rgb(33 138 255);
  --sidebar-primary-foreground: rgb(255 255 255);
  --sidebar-accent: rgb(16 16 16 / 5%);
  --sidebar-accent-foreground: rgb(16 16 16);
  --sidebar-border: rgb(16 16 16 / 8%);
  --sidebar-ring: rgb(33 138 255);

  --typeface-body: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1.5rem;
  --page-width: 77.5rem;
  --page-gutter: 1.25rem;
  --section-y: 7.5rem;
}

/* Dark (sibling): the original's #101010 as the page, charcoal cards, the same blue. */
.dark {
  --background: rgb(16 16 16);
  --foreground: rgb(242 242 242);
  --card: rgb(28 28 28);
  --card-foreground: rgb(242 242 242);
  --popover: rgb(28 28 28);
  --popover-foreground: rgb(242 242 242);
  --primary: rgb(33 138 255);
  --primary-foreground: rgb(255 255 255);
  --secondary: rgb(64 64 64);
  --secondary-foreground: rgb(242 242 242);
  --muted: rgb(40 40 40);
  --muted-foreground: rgb(255 255 255 / 64%);
  --accent: rgb(255 255 255 / 8%);
  --accent-foreground: rgb(242 242 242);
  --destructive: rgb(240 96 96);
  --destructive-foreground: rgb(16 16 16);
  --border: rgb(255 255 255 / 10%);
  --input: rgb(255 255 255 / 18%);
  --ring: rgb(70 155 250);
  --highlight: rgb(251 158 121);
  --highlight-foreground: rgb(16 16 16);
  --glow: rgb(70 155 250);
  --chart-1: rgb(70 155 250);
  --chart-2: rgb(251 158 121);
  --chart-3: rgb(150 140 190);
  --chart-4: rgb(120 165 120);
  --chart-5: rgb(200 140 105);
  --sidebar: rgb(28 28 28);
  --sidebar-foreground: rgb(242 242 242);
  --sidebar-primary: rgb(33 138 255);
  --sidebar-primary-foreground: rgb(255 255 255);
  --sidebar-accent: rgb(255 255 255 / 8%);
  --sidebar-accent-foreground: rgb(242 242 242);
  --sidebar-border: rgb(255 255 255 / 10%);
  --sidebar-ring: rgb(70 155 250);
}
